<?php
require_once __DIR__ . '/includes/auth.php';
if (database_is_ready() && system_is_setup()) { redirect('login.php'); }
$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!database_is_ready()){$error='The database is not ready. Import database.sql in phpMyAdmin first, then refresh this page.';}else{$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$username=trim($_POST['username']??'');$password=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$username===''||strlen($password)<8)$error='Use a name, valid email, username, and password with at least 8 characters.';elseif($password!==$confirm)$error='The passwords do not match.';else{db()->prepare('INSERT INTO users (full_name,email,username,password_hash,role,account_status) VALUES (?,?,?,? ,\'admin\',\'active\')')->execute([$name,$email,$username,password_hash($password,PASSWORD_DEFAULT)]);flash('success','Administrator account created. You can now sign in with Gmail OTP.');redirect('login.php');}}}
$databaseReady=database_is_ready();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>First-run setup · Barangay Information System</title><link rel="stylesheet" href="assets/app.css"></head><body class="login-page"><div class="login-card"><div class="brand login-brand"><div class="brand-mark"><span></span><span></span></div><div><strong>Barangay</strong><small>information system</small></div></div><div class="eyebrow">First-run setup</div><h1><?= $databaseReady?'Create your administrator.':'Prepare the database first.' ?></h1><p class="login-copy"><?= $databaseReady?'No account is pre-installed. The email address will receive OTP codes and security notifications.':'Import database.sql through phpMyAdmin, then refresh this page.' ?></p><?php if($error): ?><div class="flash error"><?= h($error) ?></div><?php endif; ?><?php if(!$databaseReady): ?><div class="demo-note"><strong>Database checklist</strong><span>Start MySQL → open phpMyAdmin → import database.sql → refresh this page.</span></div><?php else: ?><form method="post" class="login-form"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><label>Full name<input name="full_name" required></label><label>Administrator email<input type="email" name="email" required placeholder="admin@gmail.com"></label><label>Username<input name="username" required></label><label>Password<input type="password" name="password" minlength="8" required></label><label>Confirm password<input type="password" name="confirm_password" minlength="8" required></label><button class="primary-button full-button">Create administrator</button></form><?php endif; ?></div></body></html>
